import { readFileSync, readdirSync } from 'node:fs';
import { join } from 'node:path';

const roots = [
  ['harness', '/home/user/deepseek-harness/data/proving-ground/2026-09-08-bench-h1-harness-loop-t5/sessions'],
  ['product', '/home/user/deepseek-harness/data/proving-ground/2026-09-08-bench-h1-product-loop-t5/sessions'],
];

// env -> fleet -> set of "passed/total" and failed ids
const table = new Map();
const evidence = new Map(); // `${env}|${caseId}` -> Set of evidence strings

for (const [label, root] of roots) {
  for (const f of readdirSync(root).sort()) {
    const lines = readFileSync(join(root, f), 'utf8').split('\n').filter(Boolean);
    let env = '?';
    for (const line of lines) {
      let ev;
      try { ev = JSON.parse(line); } catch { continue; }
      if (ev.type === 'environment/run') { env = ev.data.environmentId; }
      if (ev.type !== 'verification/run') { continue; }
      for (const r of ev.data.results ?? []) {
        if (!r.cases) continue;
        const key = `${env} :: ${label}`;
        if (!table.has(key)) table.set(key, new Set());
        table.get(key).add(`${r.cases.passed}/${r.cases.total} missing=[${(r.cases.failed ?? []).map((c) => c.id).join(',')}]`);
        for (const c of r.cases.failed ?? []) {
          const ek = `${env}|${c.id}`;
          if (!evidence.has(ek)) evidence.set(ek, new Set());
          if (c.evidence) evidence.get(ek).add(c.evidence);
          for (const [k, v] of Object.entries(c)) {
            if (k !== 'id' && k !== 'weight' && k !== 'channels' && k !== 'exitClass' && typeof v === 'string') {
              evidence.get(ek).add(`${k}: ${v}`);
            }
          }
        }
      }
    }
  }
}

console.log('===== PER-CELL SUMMARY =====');
for (const k of [...table.keys()].sort()) {
  console.log(k);
  for (const v of table.get(k)) console.log('    ', v);
}

console.log('\n===== EVIDENCE =====');
for (const k of [...evidence.keys()].sort()) {
  const set = evidence.get(k);
  console.log(k, set.size ? '' : '(no evidence field)');
  for (const v of set) console.log('   >', JSON.stringify(v));
}

