26	/** A cursor over one line's text, shared by the name reader and the value reader. */
27	export class Reader {
28	  /**
29	   * @param text - the line, or the part of it still to read.
30	   */
31	  constructor(text) {
32	    this.text = text
33	    this.at = 0
34	  }
35	
