const base = '/home/user/deepseek-harness/.claude/worktrees/agent-ad8981f5014a7045d/examples/headless-agent/tests/fixtures/proving-ground-bench/environments';
const tier5 = ['uri-resolve', 'glob-brace', 'conf-canon', 'build-schedule', 'ranked-choice', 'sheet-eval', 'lex-states', 'rate-limit-sim', 'diff3-merge', 'wrap-justify'];

for (const task of tier5) {
  const p = `${base}/${task}/reference/cases.json`;
  if (!existsSync(p)) { console.log(task, 'NO CASES'); continue; }
  const cases = JSON.parse(readFileSync(p, 'utf8'));
  const hits = [];
  for (const c of cases) {
    for (const ch of ['stdout', 'stderr']) {
      const text = c[ch] ?? '';
      for (const line of text.split('\n')) {
        if (line !== line.trimEnd() && line.trim() !== '') hits.push(`${c.id} ${ch}: ${JSON.stringify(line)}`);
      }
    }
  }
  console.log(`--- ${task}: ${cases.length} cases, ${hits.length} trailing-space lines`);
  for (const h of hits.slice(0, 12)) console.log('    ', h);
  if (hits.length > 12) console.log(`     ...and ${hits.length - 12} more`);
}

